<style lang="scss" src="./mobile-stack.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import {
  MobileStackAlign,
  MobileStackAlignValues,
} from "./mobile-stack.constants";
import { has } from "../../util/has";

@Component
export default class MobileStack extends Vue {
  @Prop({ type: Number, default: 768 }) media;
  @Prop({
    type: String,
    default: MobileStackAlign.LEFT,
    validator: has(MobileStackAlignValues),
  })
  align;

  mediaQuery = null;
  currentMedia = -1;
  stackClass = "MobileStack--row";

  beforeMount() {
    this.registerMedia();
  }

  updated() {
    this.registerMedia();
  }

  beforeDestroy() {
    this.mediaQuery?.removeListener(this.handleMediaQuery);
  }

  registerMedia() {
    if (this.currentMedia === this.media) return;
    this.mediaQuery?.removeListener(this.handleMediaQuery);
    this.mediaQuery = window.matchMedia(
      `(min-width: 0px) and (max-width: ${this.media}px)`
    );
    this.handleMediaQuery(this.mediaQuery);
    this.mediaQuery.addListener(this.handleMediaQuery);
    this.currentMedia = this.media;
  }

  handleMediaQuery(query) {
    if (query.matches) {
      this.stackClass = "MobileStack--column";
    } else {
      this.stackClass = "MobileStack--row";
    }
  }
}
</script>

<template>
  <div :class="['MobileStack', stackClass, align]">
    <slot />
  </div>
</template>
